package com.citacloud.springboot.contacloud.app.views;

import com.citacloud.springboot.contacloud.app.dto.*;
import com.citacloud.springboot.contacloud.app.security.TenantContext;
import com.citacloud.springboot.contacloud.app.services.*;
import com.citacloud.springboot.contacloud.app.views.components.*;
import com.vaadin.flow.component.*;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.combobox.ComboBox;
import com.vaadin.flow.component.datepicker.DatePicker;
import com.vaadin.flow.component.dialog.Dialog;
import com.vaadin.flow.component.grid.ColumnTextAlign;
import com.vaadin.flow.component.html.*;
import com.vaadin.flow.component.icon.VaadinIcon;
import com.vaadin.flow.component.notification.Notification;
import com.vaadin.flow.component.orderedlayout.*;
import com.vaadin.flow.component.select.Select;
import com.vaadin.flow.component.tabs.*;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.data.value.ValueChangeMode;
import com.vaadin.flow.router.*;
import jakarta.annotation.security.PermitAll;

import java.math.BigDecimal;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

@Route(value="cuentas-por-pagar",layout=MainLayout.class)
@PageTitle("Cuentas por pagar | ContaCloud")
@PermitAll
public class CuentasPagarView extends VerticalLayout implements BeforeEnterObserver {
    private static final org.slf4j.Logger LOG=org.slf4j.LoggerFactory.getLogger(CuentasPagarView.class);
    private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd/MM/yyyy"),TIME=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm");
    private final CuentasPagarService service;private final EmpresaModuloService modulos;
    private final DatePicker al=new DatePicker("Al"),venceDesde=new DatePicker("Vencimiento desde"),venceHasta=new DatePicker("Vencimiento hasta");
    private final TextField buscar=new TextField("Buscar");
    private final ComboBox<CuentasPagarCatalogosDto.Opcion> proveedor=new ComboBox<>("Proveedor"),moneda=new ComboBox<>("Moneda"),sucursal=new ComboBox<>("Sucursal"),presentacion=new ComboBox<>("Moneda de visualización");
    private final Select<String> estado=new Select<>(),situacion=new Select<>();
    private final Div resumen=new Div(),aviso=new Div(),filtrosExtra=new Div();private final Span actualizado=new Span();
    private final AppGrid<CuentaPagarProveedorDto> gridProveedores=new AppGrid<>(CuentaPagarProveedorDto.class);
    private final AppGrid<CuentaPagarFacturaDto> gridFacturas=new AppGrid<>(CuentaPagarFacturaDto.class);
    private final AppGrid<AntiguedadCuentaPagarDto> gridAntiguedad=new AppGrid<>(AntiguedadCuentaPagarDto.class);
    private final AppPagination paginasProveedores,paginasFacturas,paginasAntiguedad;private final Tab tabProveedor,tabFactura,tabAntiguedad;

    public CuentasPagarView(CuentasPagarService service,EmpresaModuloService modulos){this.service=service;this.modulos=modulos;
        addClassName("cc-page");setPadding(false);setSpacing(false);setWidthFull();Button refresh=new Button(VaadinIcon.REFRESH.create(),e->cargarTodo());refresh.setTooltipText("Actualizar cuentas por pagar");refresh.getElement().setAttribute("aria-label","Actualizar cuentas por pagar");
        add(new AppPageHeader("CUENTAS POR PAGAR","Consulta, analiza y da seguimiento a las obligaciones pendientes con proveedores.",refresh));
        configurarFiltros();add(filtrosPrincipales(),filtrosExtra);resumen.addClassName("cc-balance-summary");aviso.addClassName("cc-balance-warning");aviso.setVisible(false);actualizado.addClassName("cc-balance-updated");add(resumen,actualizado,aviso);
        tabProveedor=new Tab("POR PROVEEDOR");tabFactura=new Tab("POR FACTURA");tabAntiguedad=new Tab("ANTIGÜEDAD");Tabs tabs=new Tabs(tabProveedor,tabFactura,tabAntiguedad);tabs.setWidthFull();tabs.addSelectedChangeListener(e->{mostrarVista(e.getSelectedTab());cargarVista();});add(tabs);
        configurarGrids();paginasProveedores=new AppPagination(r->cargarProveedores());paginasFacturas=new AppPagination(r->cargarFacturas());paginasAntiguedad=new AppPagination(r->cargarAntiguedad());
        add(gridProveedores,paginasProveedores,gridFacturas,paginasFacturas,gridAntiguedad,paginasAntiguedad);mostrarVista(tabProveedor);
    }

    @Override public void beforeEnter(BeforeEnterEvent event){if(!modulos.habilitado("COMPRAS")||!puede("cuentas_pagar.ver")){Notification.show("No tienes permiso para acceder a esta opción.");event.rerouteTo(DashboardView.class);return;}try{var c=service.catalogos();config(proveedor,c.proveedores());config(moneda,c.monedas());config(sucursal,c.sucursales());config(presentacion,c.monedas());c.monedas().stream().filter(x->Objects.equals(x.id(),c.monedaBaseId())).findFirst().ifPresent(presentacion::setValue);if(!puede("cuentas_pagar.ver_antiguedad"))tabAntiguedad.setVisible(false);cargarTodo();}catch(RuntimeException ex){error(ex,"No fue posible abrir Cuentas por pagar.");}}

    private void configurarFiltros(){al.setValue(LocalDate.now());al.setLocale(new Locale("es","DO"));venceDesde.setLocale(new Locale("es","DO"));venceHasta.setLocale(new Locale("es","DO"));buscar.setPlaceholder("Buscar proveedor, factura, NCF...");buscar.setClearButtonVisible(true);buscar.setValueChangeMode(ValueChangeMode.LAZY);buscar.setValueChangeTimeout(400);
        estado.setLabel("Estado");estado.setItems("Pendientes","Parcialmente pagadas","Pagadas","Todas");estado.setValue("Pendientes");situacion.setLabel("Situación");situacion.setItems("Todas","Vencidas","Vence hoy","Por vencer");situacion.setValue("Todas");
        filtrosExtra.addClassName("cc-filter-bar");filtrosExtra.add(proveedor,sucursal,venceDesde,venceHasta);filtrosExtra.setVisible(false);
        for(HasValue<?,?> f:List.<HasValue<?,?>>of(al,buscar,proveedor,moneda,sucursal,estado,situacion,venceDesde,venceHasta))f.addValueChangeListener(e->{if(e.isFromClient())reiniciar();});presentacion.addValueChangeListener(e->{if(e.isFromClient())cargarResumen();});}
    private Component filtrosPrincipales(){Button more=new Button("Más filtros",VaadinIcon.SLIDERS.create(),e->filtrosExtra.setVisible(!filtrosExtra.isVisible()));HorizontalLayout row=new HorizontalLayout(al,presentacion,buscar,estado,situacion,moneda,more);row.addClassName("cc-filter-bar");row.setAlignItems(Alignment.END);row.setWidthFull();row.expand(buscar);return row;}
    private void configurarGrids(){gridProveedores.addColumn(CuentaPagarProveedorDto::proveedor).setHeader("Proveedor").setAutoWidth(true).setFlexGrow(1);gridProveedores.addColumn(CuentaPagarProveedorDto::moneda).setHeader("Moneda").setAutoWidth(true);moneyColumn(gridProveedores.addColumn(x->money(x.porVencer())),"Por vencer");moneyColumn(gridProveedores.addColumn(x->money(x.venceHoy())),"Vence hoy");moneyColumn(gridProveedores.addColumn(x->money(x.vencido())),"Vencido");moneyColumn(gridProveedores.addColumn(x->money(x.pendiente())),"Total pendiente");moneyColumn(gridProveedores.addColumn(x->money(x.creditoDisponible())),"Crédito disponible");gridProveedores.addComponentColumn(this::accionesProveedor).setHeader("Acciones").setAutoWidth(true);gridProveedores.setEmptyStateText("No hay saldos pendientes para los filtros seleccionados.");
        gridFacturas.addColumn(CuentaPagarFacturaDto::factura).setHeader("Factura").setAutoWidth(true);gridFacturas.addColumn(CuentaPagarFacturaDto::proveedor).setHeader("Proveedor").setAutoWidth(true).setFlexGrow(1);gridFacturas.addColumn(CuentaPagarFacturaDto::numeroProveedor).setHeader("No. proveedor").setAutoWidth(true);gridFacturas.addColumn(CuentaPagarFacturaDto::numeroFiscal).setHeader("NCF / e-NCF").setAutoWidth(true);gridFacturas.addColumn(x->DATE.format(x.fecha())).setHeader("Fecha").setAutoWidth(true);gridFacturas.addColumn(x->DATE.format(x.vencimiento())).setHeader("Vencimiento").setAutoWidth(true);gridFacturas.addColumn(CuentaPagarFacturaDto::estado).setHeader("Estado").setAutoWidth(true);gridFacturas.addColumn(CuentaPagarFacturaDto::situacion).setHeader("Situación").setAutoWidth(true);moneyColumn(gridFacturas.addColumn(x->money(x.total())),"Total");moneyColumn(gridFacturas.addColumn(x->money(x.aplicado())),"Aplicado");moneyColumn(gridFacturas.addColumn(x->money(x.saldo())),"Saldo");gridFacturas.addComponentColumn(this::accionesFactura).setHeader("Acciones").setAutoWidth(true);gridFacturas.setEmptyStateText("No hay facturas para los filtros seleccionados.");
        gridAntiguedad.addColumn(AntiguedadCuentaPagarDto::proveedor).setHeader("Proveedor").setAutoWidth(true).setFlexGrow(1);gridAntiguedad.addColumn(AntiguedadCuentaPagarDto::moneda).setHeader("Moneda").setAutoWidth(true);moneyColumn(gridAntiguedad.addColumn(x->money(x.porVencer())),"Por vencer");moneyColumn(gridAntiguedad.addColumn(x->money(x.venceHoy())),"Vence hoy");moneyColumn(gridAntiguedad.addColumn(x->money(x.dias1a30())),"1-30 días");moneyColumn(gridAntiguedad.addColumn(x->money(x.dias31a60())),"31-60 días");moneyColumn(gridAntiguedad.addColumn(x->money(x.dias61a90())),"61-90 días");moneyColumn(gridAntiguedad.addColumn(x->money(x.mas90())),"Más de 90 días");moneyColumn(gridAntiguedad.addColumn(x->money(x.total())),"Total");gridAntiguedad.setEmptyStateText("No hay antigüedad de saldos para mostrar.");}

    private Component accionesProveedor(CuentaPagarProveedorDto x){HorizontalLayout row=actions();if(puede("cuentas_pagar.ver_detalle"))row.add(new AppActionButton(ActionType.VIEW,ButtonSize.GRID_ACTION,"Ver cuentas por pagar",e->detalleProveedor(x)));if(x.creditoDisponible().signum()>0&&puede("notas_credito_proveedores.aplicar"))row.add(new AppActionButton(ActionType.APPLY_CREDIT,ButtonSize.GRID_ACTION,"Aplicar crédito",e->UI.getCurrent().navigate("notas-credito-proveedores",new QueryParameters(Map.of("proveedor",List.of(x.proveedorId().toString()))))));return row;}
    private Component accionesFactura(CuentaPagarFacturaDto x){HorizontalLayout row=actions();if(puede("cuentas_pagar.ver_detalle"))row.add(new AppActionButton(ActionType.VIEW,ButtonSize.GRID_ACTION,"Ver detalle de saldo",e->detalleFactura(x)));if(puede("facturas_proveedores.ver"))row.add(new AppActionButton(ActionType.VIEW,ButtonSize.GRID_ACTION,"Ver factura",e->UI.getCurrent().navigate("facturas-proveedores",new QueryParameters(Map.of("factura",List.of(x.facturaId().toString()))))));if(x.saldo().signum()>0&&puede("pagos_proveedores.crear"))row.add(new AppActionButton(ActionType.ISSUE,ButtonSize.GRID_ACTION,"Registrar pago",e->UI.getCurrent().navigate("pagos-proveedores",new QueryParameters(Map.of("proveedor",List.of(x.proveedorId().toString()),"moneda",List.of(x.monedaId().toString()),"factura",List.of(x.facturaId().toString()))))));return row;}
    private void cargarTodo(){cargarResumen();cargarVista();}
    private void cargarVista(){if(gridProveedores.isVisible())cargarProveedores();else if(gridFacturas.isVisible())cargarFacturas();else if(gridAntiguedad.isVisible())cargarAntiguedad();}
    private void cargarProveedores(){try{var r=paginasProveedores.currentRequest();var p=service.proveedores(consulta(),r.page(),r.size());gridProveedores.setItems(p.getContent());paginasProveedores.setTotal(p.getTotalElements());}catch(RuntimeException ex){error(ex,"No fue posible cargar los saldos por proveedor.");}}
    private void cargarFacturas(){try{var r=paginasFacturas.currentRequest();var p=service.facturas(consulta(),r.page(),r.size());gridFacturas.setItems(p.getContent());paginasFacturas.setTotal(p.getTotalElements());}catch(RuntimeException ex){error(ex,"No fue posible cargar las facturas pendientes.");}}
    private void cargarAntiguedad(){if(!puede("cuentas_pagar.ver_antiguedad"))return;try{var r=paginasAntiguedad.currentRequest();var p=service.antiguedad(consulta(),r.page(),r.size());gridAntiguedad.setItems(p.getContent());paginasAntiguedad.setTotal(p.getTotalElements());}catch(RuntimeException ex){error(ex,"No fue posible cargar la antigüedad de saldos.");}}
    private void cargarResumen(){if(al.getValue()==null||presentacion.getValue()==null)return;try{var r=service.resumen(consulta(),presentacion.getValue().id());resumen.removeAll();resumen.add(
            card("TOTAL PENDIENTE",display(r.pendiente(),r,r.pendientesPorMoneda())),
            card("VENCIDO",display(r.vencido(),r,r.vencidosPorMoneda())),
            card("POR VENCER",display(r.porVencer(),r,r.porVencerPorMoneda())),
            card("VENCE HOY",display(r.venceHoy(),r,r.venceHoyPorMoneda())),
            card("CRÉDITOS DISP.",display(r.creditos(),r,r.creditosPorMoneda())),
            card("POSICIÓN NETA",display(r.posicionNeta(),r,r.posicionNetaPorMoneda())));
        actualizado.setText("Actualizado: "+r.actualizadoEn().format(TIME));if(r.consolidado())aviso.setVisible(false);else{aviso.setText(String.join(" ",r.advertencias())+" Los importes sin conversión se muestran separados por moneda.");aviso.setVisible(true);}}catch(RuntimeException ex){error(ex,"No fue posible calcular el resumen de Cuentas por pagar.");}}
    private void detalleProveedor(CuentaPagarProveedorDto x){Dialog d=dialog("CUENTAS POR PAGAR — "+x.proveedor().toUpperCase(Locale.ROOT));Div cards=new Div(card("TOTAL PENDIENTE",moneyWithSymbol(x.pendiente(),x.simbolo(),x.moneda())),card("VENCIDO",moneyWithSymbol(x.vencido(),x.simbolo(),x.moneda())),card("CRÉDITO DISPONIBLE",moneyWithSymbol(x.creditoDisponible(),x.simbolo(),x.moneda())));cards.addClassName("cc-balance-summary");AppGrid<CuentaPagarFacturaDto> g=new AppGrid<>(CuentaPagarFacturaDto.class);g.addColumn(CuentaPagarFacturaDto::factura).setHeader("Factura");g.addColumn(CuentaPagarFacturaDto::numeroProveedor).setHeader("No. proveedor");g.addColumn(v->DATE.format(v.fecha())).setHeader("Emisión");g.addColumn(v->DATE.format(v.vencimiento())).setHeader("Vencimiento");g.addColumn(CuentaPagarFacturaDto::situacion).setHeader("Situación");g.addColumn(v->money(v.total())).setHeader("Total");g.addColumn(v->money(v.aplicado())).setHeader("Aplicado");g.addColumn(v->money(v.saldo())).setHeader("Saldo");var c=new CuentasPagarService.Consulta(al.getValue(),buscar.getValue(),x.proveedorId(),x.monedaId(),id(sucursal),"PENDIENTES",keySituation(),venceDesde.getValue(),venceHasta.getValue());g.setItems(service.facturas(c,0,100).getContent());d.add(new AppDetailSection("PROVEEDOR").field("Proveedor",x.proveedor()).field("RNC / Identificación",x.identificacion()).field("Moneda",x.moneda()),cards,new H3("DOCUMENTOS PENDIENTES"),g);d.getFooter().add(new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->d.close()));d.open();}
    private void detalleFactura(CuentaPagarFacturaDto x){Dialog d=dialog("DETALLE DE SALDO — "+x.factura());Div cards=new Div(card("TOTAL FACTURA",moneyWithSymbol(x.total(),x.simbolo(),x.moneda())),card("APLICADO",moneyWithSymbol(x.aplicado(),x.simbolo(),x.moneda())),card("SALDO",moneyWithSymbol(x.saldo(),x.simbolo(),x.moneda())));cards.addClassName("cc-balance-summary");d.add(new AppDetailSection("FACTURA").field("Proveedor",x.proveedor()).field("No. proveedor",x.numeroProveedor()).field("Fecha",DATE.format(x.fecha())).field("Vencimiento",DATE.format(x.vencimiento())).field("Estado",x.estado()).field("Situación",x.situacion()),cards);if(puede("cuentas_pagar.ver_movimientos")){AppGrid<MovimientoCuentaPagarDto> g=new AppGrid<>(MovimientoCuentaPagarDto.class);g.addColumn(v->v.fecha().format(DATE)).setHeader("Fecha");g.addColumn(MovimientoCuentaPagarDto::tipo).setHeader("Tipo");g.addColumn(MovimientoCuentaPagarDto::documento).setHeader("Documento");g.addColumn(v->money(v.cargo())).setHeader("Cargo").setTextAlign(ColumnTextAlign.END);g.addColumn(v->money(v.aplicacion())).setHeader("Aplicación").setTextAlign(ColumnTextAlign.END);g.addColumn(v->money(v.saldo())).setHeader("Saldo").setTextAlign(ColumnTextAlign.END);g.setItems(service.movimientos(x.facturaId(),al.getValue()));d.add(new H3("MOVIMIENTOS DE LA CUENTA POR PAGAR"),g);}d.getFooter().add(new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->d.close()));d.open();}
    private CuentasPagarService.Consulta consulta(){return new CuentasPagarService.Consulta(al.getValue(),buscar.getValue(),id(proveedor),id(moneda),id(sucursal),keyState(),keySituation(),venceDesde.getValue(),venceHasta.getValue());}
    private String keyState(){return switch(estado.getValue()){case "Parcialmente pagadas"->"PARCIAL";case "Pagadas"->"PAGADAS";case "Todas"->"TODAS";default->"PENDIENTES";};}private String keySituation(){return switch(situacion.getValue()){case "Vencidas"->"VENCIDAS";case "Vence hoy"->"HOY";case "Por vencer"->"POR_VENCER";default->"TODAS";};}
    private void reiniciar(){if(paginasProveedores==null)return;paginasProveedores.reset();paginasFacturas.reset();paginasAntiguedad.reset();cargarTodo();}private void mostrarVista(Tab selected){boolean p=selected==tabProveedor,f=selected==tabFactura,a=selected==tabAntiguedad;gridProveedores.setVisible(p);paginasProveedores.setVisible(p);gridFacturas.setVisible(f);paginasFacturas.setVisible(f);gridAntiguedad.setVisible(a);paginasAntiguedad.setVisible(a);}
    private static void config(ComboBox<CuentasPagarCatalogosDto.Opcion> c,List<CuentasPagarCatalogosDto.Opcion> items){c.setItems(items);c.setItemLabelGenerator(CuentasPagarCatalogosDto.Opcion::nombre);c.setClearButtonVisible(true);c.setPlaceholder("Todas");}private static UUID id(ComboBox<CuentasPagarCatalogosDto.Opcion> c){return c.getValue()==null?null:c.getValue().id();}
    private static Div card(String title,String value){Span label=new Span(title),amount=new Span(value);label.addClassName("cc-balance-card-title");amount.addClassName("cc-balance-value");Div c=new Div(label,amount);c.addClassName("cc-balance-card");return c;}
    static String display(BigDecimal n,ResumenCuentasPagarDto r,Map<String,BigDecimal> amounts){
        if(n!=null)return moneyWithSymbol(n,r.simbolo(),r.moneda());
        String separated=amounts.entrySet().stream().filter(entry->entry.getValue().signum()!=0)
            .map(entry->entry.getKey()+" "+money(entry.getValue())).reduce((left,right)->left+" · "+right).orElse("");
        return separated.isBlank()?moneyWithSymbol(BigDecimal.ZERO,r.simbolo(),r.moneda()):separated;
    }
    private static String moneyWithSymbol(BigDecimal n,String symbol,String currency){String prefix=symbol==null||symbol.isBlank()?currency:symbol;return prefix+" "+money(n);}private static String money(BigDecimal n){return n==null?"—":String.format(Locale.US,"%,.2f",n);}private static <T> void moneyColumn(com.vaadin.flow.component.grid.Grid.Column<T> c,String header){c.setHeader(header).setAutoWidth(true).setTextAlign(ColumnTextAlign.END);}private static HorizontalLayout actions(){HorizontalLayout x=new HorizontalLayout();x.addClassName("cc-grid-actions");x.setSpacing(false);return x;}private static Dialog dialog(String title){Dialog d=new Dialog();d.setHeaderTitle(title);d.setWidth("min(1180px,96vw)");d.setMaxHeight("94vh");return d;}private static boolean puede(String permiso){return TenantContext.principalActual().permisos().contains(permiso);}private static void error(RuntimeException ex,String message){LOG.error(message,ex);Notification.show(message,5000,Notification.Position.BOTTOM_START);}
}
